class BrowserToolkit(Toolkit):
    """
    Browser toolkit with auto-initialization and cleanup.
    
    The browser is automatically initialized when any tool is first used,
    and automatically closed when the toolkit instance is destroyed.
    No explicit initialization or cleanup is required.
    """

    def __init__(self, name: str='BrowserToolkit', browser_type: str='chrome', headless: bool=False, timeout: int=10, **kwargs):
        browser_tool = BrowserBase(name='BrowserBase', browser_type=browser_type, headless=headless, timeout=timeout, **kwargs)
        tools = [NavigateToUrlTool(browser_tool=browser_tool), InputTextTool(browser_tool=browser_tool), BrowserClickTool(browser_tool=browser_tool), BrowserSnapshotTool(browser_tool=browser_tool), BrowserConsoleMessagesTool(browser_tool=browser_tool)]
        super().__init__(name=name, tools=tools)
        self.browser_tool = browser_tool

def __init__(self, name: str='BrowserToolkit', browser_type: str='chrome', headless: bool=False, timeout: int=10, **kwargs):
    browser_tool = BrowserBase(name='BrowserBase', browser_type=browser_type, headless=headless, timeout=timeout, **kwargs)
    tools = [NavigateToUrlTool(browser_tool=browser_tool), InputTextTool(browser_tool=browser_tool), BrowserClickTool(browser_tool=browser_tool), BrowserSnapshotTool(browser_tool=browser_tool), BrowserConsoleMessagesTool(browser_tool=browser_tool)]
    super().__init__(name=name, tools=tools)
    self.browser_tool = browser_tool

class MCPTool(Tool):
    name: str = 'MCPTool'
    description: str = 'MCP tool wrapper'
    inputs: Dict[str, Dict[str, Any]] = {}
    required: Optional[List[str]] = None
    function: Callable = None

    def __init__(self, name: str, description: str, inputs: Dict[str, Dict[str, str]], required: Optional[List[str]]=None, function: Callable=None):
        super().__init__(name=name, description=description, inputs=inputs, required=required)
        self.function = function

    @property
    def __name__(self):
        return self.name

    def __call__(self, **kwargs):
        if not self.function:
            raise ValueError('Function not set for MCPTool')
        result = self.function(**kwargs)
        return self._convert_result(result)

    def _convert_result(self, result: Any) -> Any:
        """
        Convert MCP tool results to JSON-serializable format.
        Handles complex objects like Anthropic's TextContent, ImageContent, etc.
        """
        if result is None:
            return None
        if isinstance(result, (str, int, float, bool)):
            return result
        if isinstance(result, list):
            return [self._convert_result(item) for item in result]
        if isinstance(result, dict):
            return {key: self._convert_result(value) for key, value in result.items()}
        obj_type = type(result).__name__
        if obj_type == 'TextContent':
            if hasattr(result, 'text'):
                return result.text
            elif hasattr(result, 'content'):
                return result.content
            else:
                return str(result)
        elif obj_type in ['ImageContent', 'ToolUseContent', 'ToolResultContent']:
            if hasattr(result, '__dict__'):
                return self._convert_result(result.__dict__)
            else:
                return str(result)
        if hasattr(result, 'text'):
            return result.text
        elif hasattr(result, 'content'):
            return result.content
        if hasattr(result, '__dict__'):
            return self._convert_result(result.__dict__)
        return str(result)

    @classmethod
    def validate_attributes(cls):
        required_attributes = {'name': str, 'description': str, 'inputs': dict}
        for attr, attr_type in required_attributes.items():
            if not hasattr(cls, attr):
                raise ValueError(f'Attribute {attr} is required')
            if not isinstance(getattr(cls, attr), attr_type):
                raise ValueError(f'Attribute {attr} must be of type {attr_type}')
        if cls.required:
            for required_input in cls.required:
                if required_input not in cls.inputs:
                    raise ValueError(f"Required input '{required_input}' is not found in inputs")

def __init__(self, name: str, description: str, inputs: Dict[str, Dict[str, str]], required: Optional[List[str]]=None, function: Callable=None):
    super().__init__(name=name, description=description, inputs=inputs, required=required)
    self.function = function

class SearchDDGS(SearchBase):
    """
    DDGS (Dux Distributed Global Search) tool that aggregates results from multiple search engines.
    Supports DuckDuckGo, Google, Bing, Brave, Yahoo, and other backends.
    """

    def __init__(self, name: str='SearchDDGS', num_search_pages: Optional[int]=5, max_content_words: Optional[int]=None, backend: str='auto', region: str='us-en', **kwargs):
        """
        Initialize the DDGS Search tool.
        
        Args:
            name (str): Name of the tool
            num_search_pages (int): Number of search results to retrieve
            max_content_words (int): Maximum number of words to include in content
            backend (str): Search backend(s) to use. Options: "auto", "duckduckgo", "google", "bing", "brave", "yahoo", etc.
            region (str): Search region (e.g., "us-en", "uk-en", "ru-ru")
            **kwargs: Additional keyword arguments for parent class initialization
        """
        super().__init__(name=name, num_search_pages=num_search_pages, max_content_words=max_content_words, **kwargs)
        self.backend = backend
        self.region = region

    def search(self, query: str, num_search_pages: int=None, max_content_words: int=None, backend: str=None, region: str=None) -> Dict[str, Any]:
        """
        Searches using DDGS for the given query and retrieves content from multiple pages.

        Args:
            query (str): The search query.
            num_search_pages (int): Number of search results to retrieve
            max_content_words (int): Maximum number of words to include in content, None means no limit
            backend (str): Search backend to use (overrides instance default)
            region (str): Search region to use (overrides instance default)

        Returns:
            Dict[str, Any]: Contains a list of search results and optional error message.
        """
        num_search_pages = num_search_pages or self.num_search_pages
        max_content_words = max_content_words or self.max_content_words
        backend = backend or self.backend
        region = region or self.region
        results = []
        try:
            with DDGS() as ddgs:
                search_results = list(ddgs.text(query, max_results=num_search_pages, backend=backend, region=region))
            if not search_results:
                return {'results': [], 'error': 'No search results found.'}
            for result in search_results:
                try:
                    title = result.get('title', 'No Title')
                    url = result.get('href', '') or result.get('link', '') or result.get('url', '')
                    if url and url.startswith(('http://', 'https://')):
                        try:
                            scraped_title, scraped_content = self._scrape_page(url)
                            if scraped_content:
                                title = scraped_title or title
                                content = scraped_content
                            else:
                                content = result.get('body', '')
                        except Exception:
                            content = result.get('body', '')
                    else:
                        content = result.get('body', '')
                    if content:
                        display_content = self._truncate_content(content, max_content_words)
                        results.append({'title': title, 'content': display_content, 'url': url})
                except Exception:
                    continue
            return {'results': results, 'error': None}
        except Exception as e:
            return {'results': [], 'error': str(e)}

def __init__(self, name: str='SearchDDGS', num_search_pages: Optional[int]=5, max_content_words: Optional[int]=None, backend: str='auto', region: str='us-en', **kwargs):
    """
        Initialize the DDGS Search tool.
        
        Args:
            name (str): Name of the tool
            num_search_pages (int): Number of search results to retrieve
            max_content_words (int): Maximum number of words to include in content
            backend (str): Search backend(s) to use. Options: "auto", "duckduckgo", "google", "bing", "brave", "yahoo", etc.
            region (str): Search region (e.g., "us-en", "uk-en", "ru-ru")
            **kwargs: Additional keyword arguments for parent class initialization
        """
    super().__init__(name=name, num_search_pages=num_search_pages, max_content_words=max_content_words, **kwargs)
    self.backend = backend
    self.region = region

class DDGSSearchTool(Tool):
    name: str = 'ddgs_search'
    description: str = 'Search using DDGS (Dux Distributed Global Search) which aggregates results from multiple search engines including DuckDuckGo, Google, Bing, and others'
    inputs: Dict[str, Dict[str, str]] = {'query': {'type': 'string', 'description': 'The search query to execute'}, 'num_search_pages': {'type': 'integer', 'description': 'Number of search results to retrieve. Default: 5'}, 'max_content_words': {'type': 'integer', 'description': 'Maximum number of words to include in content per result. None means no limit. Default: None'}, 'backend': {'type': 'string', 'description': "Search backend to use. Options: 'auto', 'duckduckgo', 'google', 'bing', 'brave', 'yahoo'. Default: 'auto'"}, 'region': {'type': 'string', 'description': "Search region (e.g., 'us-en', 'uk-en', 'ru-ru'). Default: 'us-en'"}}
    required: Optional[List[str]] = ['query']

    def __init__(self, search_ddgs: SearchDDGS=None):
        super().__init__()
        self.search_ddgs = search_ddgs

    def __call__(self, query: str, num_search_pages: int=None, max_content_words: int=None, backend: str=None, region: str=None) -> Dict[str, Any]:
        """Execute DDGS search using the SearchDDGS instance."""
        if not self.search_ddgs:
            raise RuntimeError('DDGS search instance not initialized')
        try:
            return self.search_ddgs.search(query, num_search_pages, max_content_words, backend, region)
        except Exception as e:
            return {'results': [], 'error': f'Error executing DDGS search: {str(e)}'}

def __init__(self, search_ddgs: SearchDDGS=None):
    super().__init__()
    self.search_ddgs = search_ddgs

