class DownloadFileTool(Tool):
    """Download a file from a Telegram contact by their name."""
    name: str = 'download_file'
    description: str = 'Download a file from a Telegram contact by their name. Downloads the file to a local directory.'
    inputs: Dict[str, Dict[str, str]] = {'contact_name': {'type': 'string', 'description': "The name of the contact to download file from (e.g., 'Vinay Kumar')"}, 'filename_query': {'type': 'string', 'description': "Filename or search query to find the file (e.g., 'Kafka.pdf')"}, 'download_dir': {'type': 'string', 'description': "Directory to download the file to (default: 'downloads')"}}
    required: List[str] = ['contact_name', 'filename_query']

    def __init__(self, telegram_base: TelegramBase):
        super().__init__()
        self.telegram_base = telegram_base

    def __call__(self, contact_name: str, filename_query: str, download_dir: str='downloads') -> Dict[str, Any]:
        """
        Download a file from a Telegram contact.
        
        Args:
            contact_name: The name of the Telegram contact
            filename_query: Filename or search query to find the file
            download_dir: Directory to download the file to
            
        Returns:
            Dictionary with download result
        """

        async def _download_file():
            client = None
            try:
                client = self.telegram_base._get_client()
                await client.start(phone=self.telegram_base.phone)
                matches = []
                async for dialog in client.iter_dialogs():
                    if contact_name.lower() in dialog.name.lower():
                        matches.append({'name': dialog.name, 'id': dialog.id, 'chat': dialog.entity})
                if len(matches) == 0:
                    return {'success': False, 'error': f"Contact '{contact_name}' not found. Please check the name."}
                if len(matches) > 1:
                    clarification_list = [f'{m['name']} (ID: {m['id']})' for m in matches]
                    return {'success': False, 'error': 'Ambiguous contact name. Please clarify which user you mean.', 'clarification_needed': clarification_list}
                chat = matches[0]['chat']
                found_message = None
                message_count = 0
                async for message in client.iter_messages(chat):
                    message_count += 1
                    if message.document:
                        doc = message.document
                        filename = 'Unknown'
                        for attribute in doc.attributes:
                            if hasattr(attribute, 'file_name'):
                                filename = attribute.file_name
                                break
                        if filename_query.lower() in filename.lower():
                            found_message = message
                            break
                    if message_count > 1000:
                        break
                if not found_message:
                    return {'success': False, 'error': f"File '{filename_query}' not found in contact '{contact_name}'"}
                if not os.path.exists(download_dir):
                    os.makedirs(download_dir)
                downloaded_path = await client.download_media(found_message, file=os.path.join(download_dir, filename))
                if downloaded_path:
                    file_size = os.path.getsize(downloaded_path)
                    return {'success': True, 'message': 'File downloaded successfully', 'filename': filename, 'file_path': downloaded_path, 'file_size': file_size, 'download_dir': download_dir, 'contact_name': contact_name}
                else:
                    return {'success': False, 'error': 'File download failed'}
            except Exception as e:
                return {'success': False, 'error': f'Failed to download file: {str(e)}'}
            finally:
                if client:
                    await client.disconnect()
        return self.telegram_base._run_async(_download_file())

