class ReadFileContentTool(Tool):
    """Read the content of a file from a Telegram contact by their name."""
    name: str = 'read_file_content'
    description: str = 'Read the content of a file from a Telegram contact by their name. Downloads the file and extracts its text content.'
    inputs: Dict[str, Dict[str, str]] = {'contact_name': {'type': 'string', 'description': "The name of the contact to read file from (e.g., 'Vinay Kumar')"}, 'filename_query': {'type': 'string', 'description': "Filename or search query to find the file (e.g., 'Kafka.pdf')"}, 'content_type': {'type': 'string', 'description': "Type of content to extract: 'full', 'first_lines', 'last_lines', 'summary' (default: 'full')"}, 'lines_count': {'type': 'integer', 'description': 'Number of lines to extract for first_lines/last_lines (default: 3)'}}
    required: List[str] = ['contact_name', 'filename_query']

    def __init__(self, telegram_base: TelegramBase):
        super().__init__()
        self.telegram_base = telegram_base

    def __call__(self, contact_name: str, filename_query: str, content_type: str='full', lines_count: int=3) -> Dict[str, Any]:
        """
        Read the content of a file from a Telegram contact.
        
        Args:
            contact_name: The name of the Telegram contact
            filename_query: Filename or search query to find the file
            content_type: Type of content to extract
            lines_count: Number of lines for first_lines/last_lines
            
        Returns:
            Dictionary with file content
        """

        async def _read_file_content():
            client = None
            try:
                client = self.telegram_base._get_client()
                await client.start(phone=self.telegram_base.phone)
                matches = []
                async for dialog in client.iter_dialogs():
                    if contact_name.lower() in dialog.name.lower():
                        matches.append({'name': dialog.name, 'id': dialog.id, 'chat': dialog.entity})
                if len(matches) == 0:
                    return {'success': False, 'error': f"Contact '{contact_name}' not found. Please check the name."}
                if len(matches) > 1:
                    clarification_list = [f'{m['name']} (ID: {m['id']})' for m in matches]
                    return {'success': False, 'error': 'Ambiguous contact name. Please clarify which user you mean.', 'clarification_needed': clarification_list}
                chat = matches[0]['chat']
                found_message = None
                message_count = 0
                async for message in client.iter_messages(chat):
                    message_count += 1
                    if message.document:
                        doc = message.document
                        filename = 'Unknown'
                        for attribute in doc.attributes:
                            if hasattr(attribute, 'file_name'):
                                filename = attribute.file_name
                                break
                        if filename_query.lower() in filename.lower():
                            found_message = message
                            break
                    if message_count > 1000:
                        break
                if not found_message:
                    return {'success': False, 'error': f"File '{filename_query}' not found in contact '{contact_name}'"}
                temp_dir = 'temp_downloads'
                if not os.path.exists(temp_dir):
                    os.makedirs(temp_dir)
                unique_filename = f'{int(time.time())}_{filename}'
                downloaded_path = await client.download_media(found_message, file=os.path.join(temp_dir, unique_filename))
                if not downloaded_path:
                    return {'success': False, 'error': 'Failed to download file for reading'}
                try:
                    if filename.lower().endswith('.pdf'):
                        with open(downloaded_path, 'rb') as file:
                            pdf_reader = PyPDF2.PdfReader(file)
                            full_text = ''
                            for page in pdf_reader.pages:
                                full_text += page.extract_text() + '\n'
                            lines = [line.strip() for line in full_text.split('\n') if line.strip()]
                            if content_type == 'full':
                                content = full_text
                            elif content_type == 'first_lines':
                                content = '\n'.join(lines[:lines_count])
                            elif content_type == 'last_lines':
                                content = '\n'.join(lines[-lines_count:])
                            elif content_type == 'summary':
                                content = f'Document has {len(pdf_reader.pages)} pages, {len(lines)} lines, {len(full_text)} characters'
                            else:
                                content = full_text
                            return {'success': True, 'message': 'File content read successfully', 'filename': filename, 'content_type': content_type, 'content': content, 'file_info': {'pages': len(pdf_reader.pages), 'lines': len(lines), 'characters': len(full_text)}, 'contact_name': contact_name}
                    else:
                        with open(downloaded_path, 'r', encoding='utf-8') as file:
                            content = file.read()
                        lines = content.split('\n')
                        if content_type == 'full':
                            processed_content = content
                        elif content_type == 'first_lines':
                            processed_content = '\n'.join(lines[:lines_count])
                        elif content_type == 'last_lines':
                            processed_content = '\n'.join(lines[-lines_count:])
                        elif content_type == 'summary':
                            processed_content = f'File has {len(lines)} lines, {len(content)} characters'
                        else:
                            processed_content = content
                        return {'success': True, 'message': 'File content read successfully', 'filename': filename, 'content_type': content_type, 'content': processed_content, 'file_info': {'lines': len(lines), 'characters': len(content)}, 'contact_name': contact_name}
                except Exception as e:
                    return {'success': False, 'error': f'Failed to read file content: {str(e)}'}
                finally:
                    try:
                        if os.path.exists(downloaded_path):
                            os.remove(downloaded_path)
                    except Exception:
                        pass
            except Exception as e:
                return {'success': False, 'error': f'Failed to read file: {str(e)}'}
            finally:
                if client:
                    await client.disconnect()
        return self.telegram_base._run_async(_read_file_content())

